def cards(names, cls):
    out=[]
    for n in names:
        href='/simone' if n=='Simone' else '#companions'
        tag='LIVE' if n=='Simone' else 'SOON'
        out.append(f'<a class="comp {cls}" href="{href}"><div class="avatar">{n[0]}</div><div><b>{n}</b><small>{tag}</small></div></a>')
    return ''.join(out)

